const PROVINCE_CODES = ["NBI","CEN","CST","EST","NEA","NYZ","RFT","WST"] as const

function slugify(input: string): string {
  return input
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

function hydrate(row: Packed, i: number): Location {
  return {
    code: i + 1,
    name: row[0],
    slug: slugify(row[0]),
    divisionCode: row[1],
    districtCode: row[2],
    formerProvinceCode: PROVINCE_CODES[row[3]],
  }
}

export const locations: readonly Location[] = packed.map(hydrate)
